// Result is a stored idempotent outcome: HTTP status and response body.
type Result struct {
	Status int
	Body   []byte
}

// Store persists pools, reservations and idempotency records.
type Store struct {
	pool *pgxpool.Pool
}

// New creates a Store backed by the given connection pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool}
}

// EnsureSchema creates all required tables and indexes. It is safe to call on
// every startup.
func (s *Store) EnsureSchema(ctx context.Context) error {
	_, err := s.pool.Exec(ctx, schemaSQL)
	return err
}

const schemaSQL = `
CREATE TABLE IF NOT EXISTS quota_pools (
    tenant_id    TEXT        NOT NULL,
    pool_id      TEXT        NOT NULL,
    limit_value  BIGINT      NOT NULL CHECK (limit_value > 0),
    valid_from   TIMESTAMPTZ NOT NULL,
    valid_until  TIMESTAMPTZ NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, pool_id),
    CHECK (valid_from < valid_until)
);

CREATE TABLE IF NOT EXISTS reservations (
    reservation_id TEXT        NOT NULL,
    tenant_id      TEXT        NOT NULL,
    pool_id        TEXT        NOT NULL,
    amount         BIGINT      NOT NULL CHECK (amount > 0),
    status         TEXT        NOT NULL CHECK (status IN ('pending','confirmed','released','expired')),
    expires_at     TIMESTAMPTZ NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    confirmed_at   TIMESTAMPTZ,
    released_at    TIMESTAMPTZ,
    PRIMARY KEY (tenant_id, pool_id, reservation_id),
    FOREIGN KEY (tenant_id, pool_id) REFERENCES quota_pools (tenant_id, pool_id)
);

CREATE INDEX IF NOT EXISTS reservations_pool_idx
    ON reservations (tenant_id, pool_id, status);

CREATE TABLE IF NOT EXISTS idempotency_records (
    tenant_id        TEXT        NOT NULL,
    idempotency_key  TEXT        NOT NULL,
    request_hash     TEXT        NOT NULL,
    method           TEXT        NOT NULL,
    path             TEXT        NOT NULL,
    response_status  INTEGER     NOT NULL,
    response_body    JSONB       NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, idempotency_key)
);
`

// PutPool creates a quota pool. It returns ErrPoolExists if the pool is
// already present; existing pools are never modified.
func (s *Store) PutPool(ctx context.Context, p Pool) error {
	_, err := s.pool.Exec(ctx, `
		INSERT INTO quota_pools (tenant_id, pool_id, limit_value, valid_from, valid_until)
		VALUES ($1, $2, $3, $4, $5)`,
		p.TenantID, p.PoolID, p.Limit, p.ValidFrom, p.ValidUntil)
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			return ErrPoolExists
		}
		return err
	}
	return nil
}

// GetPool fetches a pool for a tenant.
func (s *Store) GetPool(ctx context.Context, tenantID, poolID string) (Pool, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT tenant_id, pool_id, limit_value, valid_from, valid_until, created_at, updated_at
		FROM quota_pools WHERE tenant_id = $1 AND pool_id = $2`,
		tenantID, poolID)
	var p Pool
	err := row.Scan(&p.TenantID, &p.PoolID, &p.Limit, &p.ValidFrom, &p.ValidUntil, &p.CreatedAt, &p.UpdatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return Pool{}, ErrPoolNotFound
	}
	if err != nil {
		return Pool{}, err
	}
	return p, nil
}

// WithIdempotency runs fn under the protection of an idempotency key. Replays
// with an identical request return the stored Result without invoking fn. A key
// reused with a different request payload returns ErrIdempotencyMismatch before
// any business logic runs. The decision and fn's outcome commit atomically.
//
// The idempotency lookup happens before fn executes, satisfying the
// "idempotency precedes business validation" requirement.
func (s *Store) WithIdempotency(
	ctx context.Context,
	tenantID, key, method, path string,
	payload []byte,
	fn func(tx pgx.Tx, now time.Time) (Result, error),
) (Result, bool, error) {
	hash := fingerprint(method, path, payload)

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return Result{}, false, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	// Row-lock any existing record so concurrent replays serialize here.
	var storedHash string
	var result Result
	err = tx.QueryRow(ctx, `
		SELECT request_hash, response_status, response_body
		FROM idempotency_records
		WHERE tenant_id = $1 AND idempotency_key = $2
		FOR UPDATE`, tenantID, key).Scan(&storedHash, &result.Status, &result.Body)
	switch {
	case err == nil:
		if storedHash != hash {
			return Result{}, false, ErrIdempotencyMismatch
		}
		return result, true, nil
	case !errors.Is(err, pgx.ErrNoRows):
		return Result{}, false, err
	}

	outcome, err := fn(tx, time.Now().UTC())
	if err != nil {
		return Result{}, false, err
	}

	if _, err := tx.Exec(ctx, `
		INSERT INTO idempotency_records
		    (tenant_id, idempotency_key, request_hash, method, path, response_status, response_body)
		VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		tenantID, key, hash, method, path, outcome.Status, outcome.Body); err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			// Lost an insert race against a concurrent first request; the
			// transaction rolls back and the caller may retry to get the
			// canonical outcome.
			return Result{}, false, ErrConflict
		}
		return Result{}, false, err
	}

	if err := tx.Commit(ctx); err != nil {
		return Result{}, false, err
	}
	return outcome, false, nil
}

// CreateReservation atomically creates a pending reservation. It must run
// inside the idempotency transaction. It locks the pool row, expires any
// pending reservations past their deadline, checks pool activity and
// availability, then inserts. Available quota is the pool limit minus the
// amount of every unexpired pending or confirmed reservation.
func CreateReservation(tx pgx.Tx, ctx context.Context, now time.Time, r Reservation) (Reservation, error) {
	var limit int64
	var validFrom, validUntil time.Time
	err := tx.QueryRow(ctx, `
		SELECT limit_value, valid_from, valid_until
		FROM quota_pools
		WHERE tenant_id = $1 AND pool_id = $2
		FOR UPDATE`, r.TenantID, r.PoolID).Scan(&limit, &validFrom, &validUntil)
	if errors.Is(err, pgx.ErrNoRows) {
		return Reservation{}, ErrPoolNotFound
	}
	if err != nil {
		return Reservation{}, err
	}

	if now.Before(validFrom) || !now.Before(validUntil) {
		return Reservation{}, ErrPoolInactive
	}
	if !r.ExpiresAt.After(now) || r.ExpiresAt.After(validUntil) {
		return Reservation{}, ErrInvalidExpiry
	}

	// Release quota held by pending reservations whose deadline has passed.
	if _, err := tx.Exec(ctx, `
		UPDATE reservations
		SET status = 'expired', updated_at = $4
		WHERE tenant_id = $1 AND pool_id = $2 AND status = 'pending' AND expires_at <= $3`,
		r.TenantID, r.PoolID, now, now); err != nil {
		return Reservation{}, err
	}

	var used int64
	if err := tx.QueryRow(ctx, `
		SELECT COALESCE(SUM(amount), 0)
		FROM reservations
		WHERE tenant_id = $1 AND pool_id = $2 AND status IN ('pending', 'confirmed')`,
		r.TenantID, r.PoolID).Scan(&used); err != nil {
		return Reservation{}, err
	}
	if used+int64(r.Amount) > limit {
		return Reservation{}, ErrInsufficientQuota
	}

	created, err := insertReservation(ctx, tx, r)
	if err != nil {
		return Reservation{}, err
	}
	return created, nil
}

// ConfirmReservation marks an unexpired pending reservation confirmed. It
// expires stale pending reservations first, so an expired pending can never be
// confirmed. A conditional UPDATE makes confirm and release mutually exclusive
// under concurrency: only one can win the pending row.
func ConfirmReservation(ctx context.Context, db interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}, now time.Time, tenantID, poolID, reservationID string) (Reservation, error) {
	return transitionReservation(ctx, db, now, tenantID, poolID, reservationID, StatusConfirmed)
}

// ReleaseReservation marks an unexpired pending reservation released.
func ReleaseReservation(ctx context.Context, db interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}, now time.Time, tenantID, poolID, reservationID string) (Reservation, error) {
	return transitionReservation(ctx, db, now, tenantID, poolID, reservationID, StatusReleased)
}

func transitionReservation(
	ctx context.Context,
	db interface {
		QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	},
	now time.Time,
	tenantID, poolID, reservationID, target string,
) (Reservation, error) {
	row := db.QueryRow(ctx, `
		UPDATE reservations
		SET status      = $6,
		    confirmed_at = CASE WHEN $6 = 'confirmed' THEN $5 ELSE confirmed_at END,
		    released_at  = CASE WHEN $6 = 'released'  THEN $5 ELSE released_at END,
		    updated_at   = $5
		WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3
		  AND status = 'pending' AND expires_at > $4
		RETURNING reservation_id, tenant_id, pool_id, amount, status, expires_at,
		          created_at, updated_at, confirmed_at, released_at`,
		tenantID, poolID, reservationID, now, now, target)
	r, err := scanReservation(row)
	if errors.Is(err, pgx.ErrNoRows) {
		// Distinguish missing/cross-tenant from a wrong-state record.
		var exists bool
		err2 := db.QueryRow(ctx, `
			SELECT EXISTS (
				SELECT 1 FROM reservations
				WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3)`,
			tenantID, poolID, reservationID).Scan(&exists)
		if err2 != nil {
			return Reservation{}, err2
		}
		if !exists {
			return Reservation{}, ErrReservationNotFound
		}
		return Reservation{}, ErrNotPending
	}
	if err != nil {
		return Reservation{}, err
	}
	return r, nil
}

// GetReservation fetches a full reservation record. It returns
// ErrReservationNotFound for unknown ids or cross-tenant access.
func (s *Store) GetReservation(ctx context.Context, tenantID, poolID, reservationID string) (Reservation, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT reservation_id, tenant_id, pool_id, amount, status, expires_at,
		       created_at, updated_at, confirmed_at, released_at
		FROM reservations
		WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3`,
		tenantID, poolID, reservationID)
	r, err := scanReservation(row)
	if errors.Is(err, pgx.ErrNoRows) {
		return Reservation{}, ErrReservationNotFound
	}
	return r, err
}

// ExpirePending flips stale pending reservations to expired and releases their
// held quota. It is best-effort housekeeping; reservation creation and
// confirm/release already expire rows on their paths.
func (s *Store) ExpirePending(ctx context.Context, now time.Time) error {
	_, err := s.pool.Exec(ctx, `
		UPDATE reservations SET status = 'expired', updated_at = $2
		WHERE status = 'pending' AND expires_at <= $1`, now, now)
	return err
}

func insertReservation(ctx context.Context, tx pgx.Tx, r Reservation) (Reservation, error) {
	row := tx.QueryRow(ctx, `
		INSERT INTO reservations
		    (reservation_id, tenant_id, pool_id, amount, status, expires_at)
		VALUES ($1, $2, $3, $4, 'pending', $5)
		RETURNING reservation_id, tenant_id, pool_id, amount, status, expires_at,
		          created_at, updated_at, confirmed_at, released_at`,
		r.ReservationID, r.TenantID, r.PoolID, r.Amount, r.ExpiresAt)
	created, err := scanReservation(row)
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			return Reservation{}, ErrReservationExists
		}
		return Reservation{}, err
	}
	return created, nil
}

type scannable interface {
	Scan(dest ...any) error
}

func scanReservation(row scannable) (Reservation, error) {
	var r Reservation
	err := row.Scan(
		&r.ReservationID, &r.TenantID, &r.PoolID, &r.Amount, &r.Status,
		&r.ExpiresAt, &r.CreatedAt, &r.UpdatedAt, &r.ConfirmedAt, &r.ReleasedAt,
	)
	return r, err
}

// fingerprint hashes the request method, path and body so replays with a
// different payload are rejected while identical replays return the original
// result.
func fingerprint(method, path string, payload []byte) string {
	h := sha256.New()
	_, _ = h.Write([]byte(method))
	_ = h.Write([]byte{0})
	_, _ = h.Write([]byte(path))
	_ = h.Write([]byte{0})
	_, _ = h.Write(payload)
	return hex.EncodeToString(h.Sum(nil))
}

// EncodeBody canonicalizes a response body to JSON for storage.
func EncodeBody(v any) ([]byte, error) {
	return json.Marshal(v)
}

