// Package httpapi exposes the quota pool and reservation HTTP API.
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
	"time"

	"github.com/lansolocoder/cla03-entitlement-service/internal/store"
)

// maxBodyBytes caps request bodies to keep malformed uploads bounded.
const maxBodyBytes = 1 << 16

// dbTimeout bounds every database call made while serving a request.
const dbTimeout = 5 * time.Second

type api struct {
	store   *store.Store
	checkDB func(context.Context) error
}

// New builds the HTTP handler. checkDatabase powers the readiness probe and
// st provides quota persistence.
func New(checkDatabase func(context.Context) error, st *store.Store) http.Handler {
	a := &api{store: st, checkDB: checkDatabase}
	mux := http.NewServeMux()

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		respond(w, http.StatusOK, `{"status":"ok"}`)
	})
	mux.HandleFunc("GET /readyz", a.ready)

	mux.HandleFunc("PUT /v1/tenants/{tenantId}/quota-pools/{poolId}", a.putPool)
	mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations", a.createReservation)
	mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}/confirm", a.confirmReservation)
	mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}/release", a.releaseReservation)
	mux.HandleFunc("GET /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}", a.getReservation)

	return mux
}

func (a *api) ready(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), time.Second)
	defer cancel()
	if a.checkDB == nil || a.store == nil {
		respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
		return
	}
	if err := a.checkDB(ctx); err != nil {
		log.Printf("readiness check failed: %v", err)
		respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
		return
	}
	respond(w, http.StatusOK, `{"status":"ready"}`)
}

type putPoolRequest struct {
	Limit      *int64 `json:"limit"`
	ValidFrom  string `json:"validFrom"`
	ValidUntil string `json:"validUntil"`
}

func (a *api) putPool(w http.ResponseWriter, r *http.Request) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")

	var req putPoolRequest
	if err := decodeStrict(r, &req); err != nil {
		fail(w, http.StatusBadRequest)
		return
	}
	if req.Limit == nil || *req.Limit <= 0 ||
		req.ValidFrom == "" || req.ValidUntil == "" {
		fail(w, http.StatusBadRequest)
		return
	}
	validFrom, err := time.Parse(time.RFC3339, req.ValidFrom)
	if err != nil {
		fail(w, http.StatusBadRequest)
		return
	}
	validUntil, err := time.Parse(time.RFC3339, req.ValidUntil)
	if err != nil {
		fail(w, http.StatusBadRequest)
		return
	}
	if !validFrom.Before(validUntil) {
		fail(w, http.StatusBadRequest)
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	pool, err := a.store.PutPool(ctx, store.Pool{
		TenantID:   tenantID,
		PoolID:     poolID,
		Limit:      int(*req.Limit),
		ValidFrom:  validFrom.UTC(),
		ValidUntil: validUntil.UTC(),
	})
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	writeJSON(w, http.StatusCreated, pool)
}

type createReservationRequest struct {
	ReservationID string `json:"reservationId"`
	Amount        *int64 `json:"amount"`
	ExpiresAt     string `json:"expiresAt"`
}

func (a *api) createReservation(w http.ResponseWriter, r *http.Request) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")

	// Idempotency-Key is mandatory for every POST and is enforced before the
	// request body is interpreted.
	key := strings.TrimSpace(r.Header.Get("Idempotency-Key"))
	if key == "" || len(key) > 255 {
		fail(w, http.StatusBadRequest)
		return
	}

	raw, canonical, ok := readCanonicalBody(w, r)
	if !ok {
		return
	}

	var req createReservationRequest
	if err := json.Unmarshal(canonical, &req); err != nil {
		fail(w, http.StatusBadRequest)
		return
	}
	// Field-level (syntactic) validation is deferred into the idempotent
	// transaction, so a replay of an accepted request always returns the
	// stored result even if the clock has since moved: idempotency is decided
	// before business validation runs.

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	result, _, err := a.store.WithIdempotency(ctx, tenantID, key, r.Method, r.URL.Path, raw,
		func(txCtx pgxTx, now time.Time) (store.Result, error) {
			return a.doCreateReservation(txCtx, now, tenantID, poolID, req)
		})
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	respond(w, result.Status, string(result.Body))
}

// pgxTx is the transaction type expected by business functions; it is an alias
// kept in handler signatures to avoid importing pgx everywhere.
type pgxTx = txLike

func (a *api) doCreateReservation(ctx context.Context, now time.Time, tenantID, poolID string, req createReservationRequest) (store.Result, error) {
	if req.ReservationID == "" || req.Amount == nil || *req.Amount <= 0 || req.ExpiresAt == "" {
		return store.Result{}, errInvalidRequest
	}
	expiresAt, err := time.Parse(time.RFC3339, req.ExpiresAt)
	if err != nil {
		return store.Result{}, errInvalidRequest
	}
	created, err := store.CreateReservation(ctx, now, store.Reservation{
		ReservationID: req.ReservationID,
		TenantID:      tenantID,
		PoolID:        poolID,
		Amount:        int(*req.Amount),
		ExpiresAt:     expiresAt.UTC(),
	})
	if err != nil {
		return store.Result{}, err
	}
	body, err := json.Marshal(created)
	if err != nil {
		return store.Result{}, err
	}
	return store.Result{Status: http.StatusCreated, Body: body}, nil
}

func (a *api) confirmReservation(w http.ResponseWriter, r *http.Request) {
	a.transition(w, r, store.ConfirmReservation)
}

func (a *api) releaseReservation(w http.ResponseWriter, r *http.Request) {
	a.transition(w, r, store.ReleaseReservation)
}

type transitionFunc func(context.Context, pgxTx, time.Time, string, string, string) (store.Reservation, error)

func (a *api) transition(w http.ResponseWriter, r *http.Request, do transitionFunc) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")
	reservationID := r.PathValue("reservationId")

	key := strings.TrimSpace(r.Header.Get("Idempotency-Key"))
	if key == "" || len(key) > 255 {
		fail(w, http.StatusBadRequest)
		return
	}

	raw, _, ok := readCanonicalBody(w, r)
	if !ok {
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	result, _, err := a.store.WithIdempotency(ctx, tenantID, key, r.Method, r.URL.Path, raw,
		func(tx pgxTx, now time.Time) (store.Result, error) {
			updated, err := do(ctx, tx, now, tenantID, poolID, reservationID)
			if err != nil {
				return store.Result{}, err
			}
			body, err := json.Marshal(updated)
			if err != nil {
				return store.Result{}, err
			}
			return store.Result{Status: http.StatusOK, Body: body}, nil
		})
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	respond(w, result.Status, string(result.Body))
}

func (a *api) getReservation(w http.ResponseWriter, r *http.Request) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")
	reservationID := r.PathValue("reservationId")

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	reservation, err := a.store.GetReservation(ctx, tenantID, poolID, reservationID)
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, reservation)
}

// errInvalidRequest marks field-level validation failures discovered inside a
// transaction; they map to 400 and never persist an idempotency record.
var errInvalidRequest = errors.New("invalid request")

// readCanonicalBody reads the request body and returns both the raw bytes and
// a canonical JSON form (sorted keys, no insignificant whitespace). An empty
// body is legal for action endpoints and yields nil. Malformed JSON or a body
// carrying multiple JSON values is rejected with 400 before any database call.
func readCanonicalBody(w http.ResponseWriter, r *http.Request) (raw, canonical []byte, ok bool) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
	raw, err := io.ReadAll(r.Body)
	if err != nil {
		fail(w, http.StatusBadRequest)
		return nil, nil, false
	}
	if len(strings.TrimSpace(string(raw))) == 0 {
		return nil, nil, true
	}
	canonical, err = store.CanonicalPayload(raw)
	if err != nil {
		fail(w, http.StatusBadRequest)
		return nil, nil, false
	}
	return raw, canonical, true
}

// decodeStrict decodes a JSON request body rejecting unknown fields, trailing
// content and multiple JSON values.
func decodeStrict(r *http.Request, dst any) error {
	r.Body = http.MaxBytesReader(nil, r.Body, maxBodyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("multiple JSON values")
	}
	return nil
}

// writeStoreError maps persistence-layer outcomes to public status codes.
// Internal details are logged but never sent to clients.
func writeStoreError(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, errInvalidRequest):
		fail(w, http.StatusBadRequest)
	case errors.Is(err, store.ErrPoolExists),
		errors.Is(err, store.ErrReservationExists),
		errors.Is(err, store.ErrPoolInactive),
		errors.Is(err, store.ErrInsufficientQuota),
		errors.Is(err, store.ErrInvalidExpiry),
		errors.Is(err, store.ErrNotPending),
		errors.Is(err, store.ErrIdempotencyMismatch):
		fail(w, http.StatusConflict)
	case errors.Is(err, store.ErrPoolNotFound):
		// Pool creation is the only PUT path; creating inside a missing
		// tenant scope cannot happen. A reservation create against a missing
		// pool fails the "pool must be active" precondition, i.e. a conflict.
		fail(w, http.StatusConflict)
	case errors.Is(err, store.ErrReservationNotFound):
		fail(w, http.StatusNotFound)
	default:
		log.Printf("%s %s: storage failure: %v", r.Method, r.URL.Path, err)
		fail(w, http.StatusServiceUnavailable)
	}
}

func fail(w http.ResponseWriter, status int) {
	messages := map[int]string{
		http.StatusBadRequest:          "invalid request",
		http.StatusNotFound:            "not found",
		http.StatusConflict:            "conflict",
		http.StatusServiceUnavailable:  "service unavailable",
	}
	writeJSON(w, status, map[string]string{"error": messages[status]})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	body, err := json.Marshal(v)
	if err != nil {
		log.Printf("failed to encode response: %v", err)
		respond(w, http.StatusServiceUnavailable, `{"error":"service unavailable"}`)
		return
	}
	respond(w, status, string(body))
}

func respond(w http.ResponseWriter, status int, body string) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(body + "\n"))
}

