// pgxTx is the transaction type expected by business functions; it is an alias
// kept in handler signatures to avoid importing pgx everywhere.
type pgxTx = txLike

func (a *api) doCreateReservation(ctx context.Context, now time.Time, tenantID, poolID string, req createReservationRequest) (store.Result, error) {
