	}
	expiresAt, err := time.Parse(time.RFC3339, req.ExpiresAt)
	if err != nil {
		return store.Result{}, errInvalidRequest
	}
	created, err := store.CreateReservation(ctx, now, store.Reservation{
		ReservationID: req.ReservationID,
		TenantID:      tenantID,
		PoolID:        poolID,
		Amount:        int(*req.Amount),
		ExpiresAt:     expiresAt.UTC(),
	})
