	if err != nil {
		return store.Result{}, err
	}
	return store.Result{Status: http.StatusCreated, Body: body}, nil
}

func (a *api) confirmReservation(w http.ResponseWriter, r *http.Request) {
	a.transition(w, r, store.ConfirmReservation)
}

func (a *api) releaseReservation(w http.ResponseWriter, r *http.Request) {
	a.transition(w, r, store.ReleaseReservation)
}

type transitionFunc func(context.Context, pgxTx, time.Time, string, string, string) (store.Reservation, error)

func (a *api) transition(w http.ResponseWriter, r *http.Request, do transitionFunc) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")
	reservationID := r.PathValue("reservationId")

	key := strings.TrimSpace(r.Header.Get("Idempotency-Key"))
	if key == "" || len(key) > 255 {
		fail(w, http.StatusBadRequest)
		return
	}

	raw, _, ok := readCanonicalBody(w, r)
	if !ok {
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	result, _, err := a.store.WithIdempotency(ctx, tenantID, key, r.Method, r.URL.Path, raw,
		func(tx pgxTx, now time.Time) (store.Result, error) {
			updated, err := do(ctx, tx, now, tenantID, poolID, reservationID)
			if err != nil {
				return store.Result{}, err
			}
			body, err := json.Marshal(updated)
			if err != nil {
				return store.Result{}, err
			}
			return store.Result{Status: http.StatusOK, Body: body}, nil
		})
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	respond(w, result.Status, string(result.Body))
}

func (a *api) getReservation(w http.ResponseWriter, r *http.Request) {
	tenantID := r.PathValue("tenantId")
	poolID := r.PathValue("poolId")
	reservationID := r.PathValue("reservationId")

	ctx, cancel := context.WithTimeout(r.Context(), dbTimeout)
	defer cancel()
	reservation, err := a.store.GetReservation(ctx, tenantID, poolID, reservationID)
	if err != nil {
		writeStoreError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, reservation)
