// errInvalidRequest marks field-level validation failures discovered inside a
// transaction; they map to 400 and never persist an idempotency record.
var errInvalidRequest = errors.New("invalid request")

// readCanonicalBody reads the request body and returns both the raw bytes and
// a canonical JSON form (sorted keys, no insignificant whitespace). An empty
// body is legal for action endpoints and yields nil. Malformed JSON or a body
// carrying multiple JSON values is rejected with 400 before any database call.
func readCanonicalBody(w http.ResponseWriter, r *http.Request) (raw, canonical []byte, ok bool) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
	raw, err := io.ReadAll(r.Body)
	if err != nil {
		fail(w, http.StatusBadRequest)
