	}
	if len(strings.TrimSpace(string(raw))) == 0 {
		return nil, nil, true
	}
	canonical, err = store.CanonicalPayload(raw)
	if err != nil {
		fail(w, http.StatusBadRequest)
		return nil, nil, false
	}
	return raw, canonical, true
}

// decodeStrict decodes a JSON request body rejecting unknown fields, trailing
// content and multiple JSON values.
func decodeStrict(r *http.Request, dst any) error {
	r.Body = http.MaxBytesReader(nil, r.Body, maxBodyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("multiple JSON values")
	}
	return nil
}

// writeStoreError maps persistence-layer outcomes to public status codes.
// Internal details are logged but never sent to clients.
func writeStoreError(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, errInvalidRequest):
		fail(w, http.StatusBadRequest)
	case errors.Is(err, store.ErrPoolExists),
		errors.Is(err, store.ErrReservationExists),
		errors.Is(err, store.ErrPoolInactive),
		errors.Is(err, store.ErrInsufficientQuota),
		errors.Is(err, store.ErrInvalidExpiry),
		errors.Is(err, store.ErrNotPending),
		errors.Is(err, store.ErrIdempotencyMismatch):
		fail(w, http.StatusConflict)
	case errors.Is(err, store.ErrPoolNotFound):
