// WithIdempotency runs fn under the protection of an idempotency key. An
// identical replay returns the stored Result without invoking fn (replayed is
// true). A key reused with a different request payload returns
// ErrIdempotencyMismatch before any business logic runs. The replay decision,
// fn's outcome and the stored record commit atomically.
//
// Only successful outcomes are persisted; business failures roll back and can
// be retried under the same key.
func (s *Store) WithIdempotency(
	ctx context.Context,
	tenantID, key, method, path string,
	payload []byte,
	fn func(tx pgx.Tx, now time.Time) (Result, error),
) (result Result, replayed bool, err error) {
	hash := fingerprint(method, path, payload)

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return Result{}, false, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	stored, found, err := lookupIdempotency(ctx, tx, tenantID, key)
	if err != nil {
		return Result{}, false, err
	}
	if found {
		if stored.requestHash != hash {
			return Result{}, false, ErrIdempotencyMismatch
		}
		return stored.result, true, nil
	}

	outcome, err := fn(tx, s.now())
	if err != nil {
		return Result{}, false, err
	}

	if _, err := tx.Exec(ctx, `
		INSERT INTO idempotency_records
		    (tenant_id, idempotency_key, request_hash, method, path, response_status, response_body)
		VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		tenantID, key, hash, method, path, outcome.Status, outcome.Body); err != nil {
		var pgErr *pgconn.PgError
		if !errors.As(err, &pgErr) || pgErr.Code != uniqueViolation {
			return Result{}, false, err
		}
		// A concurrent request with the same key won the insert race. Its
		// business outcome is the canonical one; this attempt rolls back
		// completely and we return what the winner stored.
		if err := tx.Rollback(ctx); err != nil {
			return Result{}, false, err
		}
		return s.readIdempotency(ctx, tenantID, key, hash)
	}

	if err := tx.Commit(ctx); err != nil {
		return Result{}, false, err
	}
	return outcome, false, nil
}

type storedIdempotency struct {
	requestHash string
	result      Result
}

func lookupIdempotency(ctx context.Context, tx pgx.Tx, tenantID, key string) (storedIdempotency, bool, error) {
	var rec storedIdempotency
	err := tx.QueryRow(ctx, `
		SELECT request_hash, response_status, response_body
		FROM idempotency_records
		WHERE tenant_id = $1 AND idempotency_key = $2
		FOR UPDATE`, tenantID, key).Scan(&rec.requestHash, &rec.result.Status, &rec.result.Body)
	if errors.Is(err, pgx.ErrNoRows) {
		return storedIdempotency{}, false, nil
	}
	if err != nil {
		return storedIdempotency{}, false, err
	}
	return rec, true, nil
}

func (s *Store) readIdempotency(ctx context.Context, tenantID, key, expectedHash string) (Result, bool, error) {
	var rec storedIdempotency
	err := s.pool.QueryRow(ctx, `
		SELECT request_hash, response_status, response_body
		FROM idempotency_records
		WHERE tenant_id = $1 AND idempotency_key = $2`,
		tenantID, key).Scan(&rec.requestHash, &rec.result.Status, &rec.result.Body)
	if errors.Is(err, pgx.ErrNoRows) {
		// Winner rolled back too (its business failed); caller can retry.
		return Result{}, false, ErrConcurrentRetry
	}
	if err != nil {
		return Result{}, false, err
	}
	if rec.requestHash != expectedHash {
		return Result{}, false, ErrIdempotencyMismatch

	return rec.result, true, nil
}

// ErrConcurrentRetry signals a lost concurrency race whose winner did not store
// an outcome either; the request may be safely retried.
var ErrConcurrentRetry = errors.New("concurrent request retry")

input.new_string:
// WithIdempotency runs fn under the protection of an idempotency key. An
// identical replay returns the stored Result without invoking fn (replayed is
// true, always with HTTP semantics the caller maps to 200). A key reused with
// a different request payload returns ErrIdempotencyMismatch before any
// business logic runs. The claim, fn's outcome and the stored result commit
// atomically.
//
// Concurrency is handled with a claim protocol: the first request inserts a
// placeholder row that concurrent same-key requests block on; when the owner
// commits they read the canonical outcome, and if the owner rolls back one of
// them takes over the claim. Business failures store nothing.
func (s *Store) WithIdempotency(
	ctx context.Context,
	tenantID, key, method, path string,
	payload []byte,
	fn func(tx pgx.Tx, now time.Time) (Result, error),
) (result Result, replayed bool, err error) {
	hash := fingerprint(method, path, payload)

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return Result{}, false, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	for {
		var claimed bool
		err = tx.QueryRow(ctx, `
			INSERT INTO idempotency_records
			    (tenant_id, idempotency_key, request_hash, method, path)
			VALUES ($1, $2, $3, $4, $5)
			ON CONFLICT DO NOTHING
			RETURNING TRUE`,
			tenantID, key, hash, method, path).Scan(&claimed)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return Result{}, false, err
		}
		if claimed {
			break
		}

		// A concurrent request owns (or owned) the key. Block on its row
		// until it commits or rolls back.
		var storedHash string
		var status *int
		var body []byte
		err = tx.QueryRow(ctx, `
			SELECT request_hash, response_status, response_body
			FROM idempotency_records
			WHERE tenant_id = $1 AND idempotency_key = $2
			FOR UPDATE`, tenantID, key).Scan(&storedHash, &status, &body)
